"""Что есть в СЕРВЕРНОМ бандле панели, чего нет в моей сборке.

Серверный собран сегодня в 02:27 UTC с исходника, которого нет в гите
(в ветках свежее 12.08 по web/src ничего). Если там найдутся видимые
строки, которых у меня нет, значит соседняя сессия добавила экран или
поле - и класть свой бандл поверх нельзя, это молчаливый откат чужой
работы. Сравнение делаем ЗДЕСЬ, чтобы наружу ушла только разница:
полный список строк не влезает в предел вывода задания.
"""
import base64
import io
import json
import re
import zlib

МОИ = set(json.loads(zlib.decompress(base64.b64decode("")).decode()))
путь = r"C:\sender\sender\web\dist\assets\index--uc0XN03.js"
т = io.open(путь, encoding="utf-8", errors="replace").read()
серверные = {s.strip() for s in
              re.findall(r"[А-Яа-яЁё][А-Яа-яЁё \-:,()«»0-9]{3,60}", т)}
только_там = sorted(серверные - МОИ)
только_тут = sorted(МОИ - серверные)
print(f"строк: сервер {len(серверные)}, моя сборка {len(МОИ)}")
print(f"\nЕСТЬ ТОЛЬКО НА СЕРВЕРЕ: {len(только_там)}")
for с in только_там[:60]:
    print("   " + с[:80])
print(f"\nесть только у меня: {len(только_тут)}")
for с in только_тут[:30]:
    print("   " + с[:80])
